 * Parses a limiter file into declared policies, routes and a validated event
 * log. All validation happens here: by the time `parse` returns, the
 * simulator can replay the events without any further chance of error.
 */

import { Bucket, Window } from './policies.js'

const TOKEN_RE = /^[A-Za-z0-9_./:-]+$/
const INT_RE = /^(0|[1-9][0-9]*)$/

export class ParseError extends Error {
  constructor(line, reason) {
    super(`line ${line}: ${reason}`)
    this.line = line
    this.reason = reason
  }
}

function parseCount(token, field, min) {
  if (!INT_RE.test(token) || BigInt(token) < min) {
    throw new Error(`${field} must be an integer of at least ${min}`)
  }
  return BigInt(token)
}

/**
 * Splits the raw file into non-empty, non-comment, whitespace-tokenized
 * lines, each tagged with its 1-based source line number.
 */
function tokenizeLines(text) {
  const rawLines = text.split('\n')
  if (rawLines.length > 0 && rawLines[rawLines.length - 1] === '') rawLines.pop()
  const lines = []
  for (let i = 0; i < rawLines.length; i++) {
    const trimmed = rawLines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    lines.push({ number: i + 1, tokens: trimmed.split(/\s+/) })
  }
  return lines
}

export function parse(text) {
  const policies = new Map() // name -> Bucket | Window instance
  const routes = [] // { prefix, policyNames: string[] }
  const routePrefixes = new Set()
  const events = [] // { tick: BigInt, key: string }

  let sawEvent = false
  let lastTick = null

  for (const { number: lineNumber, tokens } of tokenizeLines(text)) {
    const directive = tokens[0]
    try {
      switch (directive) {
        case 'bucket': {
          if (sawEvent) throw new Error('declarations must come before the first event')
          if (tokens.length !== 5) throw new Error('expected bucket <name> <capacity> <refill> <per>')
          const [, name, capacityTok, refillTok, perTok] = tokens
          if (!TOKEN_RE.test(name)) throw new Error(`invalid policy name ${name}`)
          if (policies.has(name)) throw new Error(`policy ${name} is declared twice`)
          const capacity = parseCount(capacityTok, 'capacity', 1n)
          const refill = parseCount(refillTok, 'refill', 0n)
          const per = parseCount(perTok, 'per', 1n)
          policies.set(name, new Bucket(capacity, refill, per))
          break
        }
        case 'window': {
          if (sawEvent) throw new Error('declarations must come before the first event')
          if (tokens.length !== 4) throw new Error('expected window <name> <limit> <span>')
          const [, name, limitTok, spanTok] = tokens
          if (!TOKEN_RE.test(name)) throw new Error(`invalid policy name ${name}`)
          if (policies.has(name)) throw new Error(`policy ${name} is declared twice`)
          const limit = parseCount(limitTok, 'limit', 0n)
          const span = parseCount(spanTok, 'span', 1n)
          policies.set(name, new Window(limit, span))
          break
        }
        case 'route': {
          if (sawEvent) throw new Error('declarations must come before the first event')
          if (tokens.length < 3) throw new Error('expected route <prefix> <policy>...')
          const [, prefix, ...policyNames] = tokens
          if (!TOKEN_RE.test(prefix)) throw new Error(`invalid route prefix ${prefix}`)
          if (routePrefixes.has(prefix)) throw new Error(`prefix ${prefix} is routed twice`)
          for (const name of policyNames) {
            if (!policies.has(name)) throw new Error(`unknown policy ${name}`)
          }
          routePrefixes.add(prefix)
          routes.push({ prefix, policyNames })
          break
        }
        case 'event': {
          if (tokens.length !== 3) throw new Error('expected event <tick> <key>')
          const [, tickTok, key] = tokens
          const tick = parseCount(tickTok, 'tick', 0n)
          if (!TOKEN_RE.test(key)) throw new Error(`invalid key ${key}`)
          if (lastTick !== null && tick < lastTick) throw new Error(`tick ${tick} is before tick ${lastTick}`)
          lastTick = tick
          sawEvent = true
          events.push({ tick, key })
          break
        }
        default:
          throw new Error(`unknown directive ${directive}`)
      }
    } catch (err) {
      throw new ParseError(lineNumber, err.message)
    }
  }

  return { policies, routes, events }
}

/** Finds the route with the longest prefix matching `key`, or null. */
export function findRoute(routes, key) {
  let best = null
  for (const route of routes) {
    if (key.startsWith(route.prefix)) {
      if (best === null || route.prefix.length > best.prefix.length) best = route
    }
  }
  return best
}
"}

