 * Replays a parsed limiter file's events against its policies, either as a
 * per-event verdict log (`replay`) or a per-key tally (`summary`).
 */

import { findRoute } from './parse.js'

/**
 * Runs the events in order, calling `onVerdict(event, allowed, denierName)`
 * for each one. `denierName` is the name of the first policy on the event's
 * route that refused, or null when the event was allowed.
 */
export function run({ policies, routes, events }, onVerdict) {
  for (const event of events) {
    const { tick, key } = event
    const route = findRoute(routes, key)
    if (route === null) {
      onVerdict(event, true, null)
      continue
    }

    const policyList = route.policyNames.map((name) => policies.get(name))
    for (const policy of policyList) policy.advance(key, tick)

    let denierIndex = -1
    for (let i = 0; i < policyList.length; i++) {
      if (!policyList[i].allows(key)) {
        denierIndex = i
        break
      }
    }

    if (denierIndex === -1) {
      for (const policy of policyList) policy.record(key, tick)
      onVerdict(event, true, null)
    } else {
      onVerdict(event, false, route.policyNames[denierIndex])
    }
  }
}

export function replay(parsed) {
  const lines = []
  run(parsed, (event, allowed, denier) => {
    lines.push(allowed ? `${event.tick} ${event.key} allow` : `${event.tick} ${event.key} deny ${denier}`)
  })
  return lines
}

export function summarize(parsed) {
  const order = []
  const totals = new Map() // key -> { allowed, denied }
  run(parsed, (event, allowed) => {
    let totalsForKey = totals.get(event.key)
    if (totalsForKey === undefined) {
      totalsForKey = { allowed: 0, denied: 0 }
      totals.set(event.key, totalsForKey)
      order.push(event.key)
    }
    if (allowed) totalsForKey.allowed++
    else totalsForKey.denied++
  })

  const lines = []
  let totalAllowed = 0
  let totalDenied = 0
  for (const key of [...order].sort()) {
    const { allowed, denied } = totals.get(key)
    lines.push(`${key} allowed=${allowed} denied=${denied}`)
    totalAllowed += allowed
    totalDenied += denied
  }
  lines.push(`total allowed=${totalAllowed} denied=${totalDenied}`)
  return lines
}
"}

